def _need(sl_L1, sigma_star):
    """the r300 frozen NEFF need: NEED = 2 sl_L1 - sigma* (exact);
    the r303-m1 mutant halves the mass exponent (1 x sl_L1)."""
    return 2 * sl_L1 - sigma_star


def _margin_chain(sigma_star, sl_L1, sl_neff, sl_nact, sl_chi,
                  sl_surv, halved_mutant=False):
    """the r303 exact slack propagation: from a CONSISTENT slope set
    (the three gated product identities r300/r301/r302 define sl_D,
    sl_cv2p, sl_natom) the four target margins m_D / m_NEFF /
    m_UNIF / m_ATOM -- pairwise EQUAL by algebra; the mutant uses
    the halved mass exponent in NEED only (the r303-m1 form)."""
    sl_D = 2 * sl_L1 - sl_neff                      # r300 identity
    sl_cv2p = sl_nact - sl_neff                     # r301 identity
    sl_natom = sl_nact + sl_chi - 2 * sl_surv - sl_cv2p   # r302
    need = (1 if halved_mutant else 2) * sl_L1 - sigma_star
    unif_need = sl_nact - need
    atom_need = sl_nact + sl_chi - 2 * sl_surv - unif_need
    return (sigma_star - sl_D,                      # m_D
            sl_neff - need,                         # m_NEFF
            unif_need - sl_cv2p,                    # m_UNIF
            sl_natom - atom_need)                   # m_ATOM


def _blocks_stats(dc, breaks):
    """exact block statistics of an atom profile dc split at the
    0-based position indices in breaks (blocks are runs of
    consecutive positions; the r301/r302 toy convention): returns
    dict with P (block sums), n_act, CV2, chi = D/Q, surv, n_eff_atom
    and the within-block lag cross sums T_k (the r304-F2 objects)."""
    cuts = [0] + list(breaks) + [len(dc)]
    blocks = [dc[a:b] for a, b in zip(cuts[:-1], cuts[1:])]
    P = [sum(b) for b in blocks]
    Q = sum(x * x for x in dc)
    L1a = sum(abs(x) for x in dc)
    D = sum(p * p for p in P)
    L1 = sum(abs(p) for p in P)
    n_act = sum(1 for p in P if p != 0)
    mu = _Fr(sum(abs(p) for p in P), n_act)
    var = sum((abs(p) - mu) ** 2 for p in P if p != 0) / _Fr(n_act)
    kmax = max(len(b) for b in blocks)
    T = {}
    for k in range(1, kmax):
        T[k] = sum(b[i] * b[i + k]
                   for b in blocks for i in range(len(b) - k))
    return dict(P=P, n_act=n_act, cv2=var / mu ** 2, chi=D / Q,
                surv=L1 / L1a, natom=L1a ** 2 / Q,
                neff=L1 ** 2 / D, D=D, Q=Q, T=T)


def _coherence_lhs(st):
    """the r302 coherence identity in product form (exact):
    (1 + CV^2) x surv^2 x n_eff_atom  ==  n_act x chi."""
    return (1 + st["cv2"]) * st["surv"] ** 2 * st["natom"]


def _chi_lag(st, factor_one_mutant=False):
    """the r304-F2 exact lag decomposition of the coherence factor:
    chi = 1 + 2 sum_k T_k/Q (the mutant drops the factor 2)."""
    fac = 1 if factor_one_mutant else 2
    return 1 + fac * sum(st["T"].values()) / _Fr(st["Q"])


def _rho_profile(z, center=True):
    """the exact centered lag-correlation profile rho_k =
    S_k / A_0 of a rational profile (the r303/r304 object); the
    uncentered mutant skips the mean removal (the r304-m3 form)."""
    n = len(z)
    m = sum(z) / _Fr(n) if center else _Fr(0)
    zc = [x - m for x in z]
    a0 = sum(x * x for x in zc)
    return [sum(zc[i] * zc[i + k] for i in range(n - k)) / a0
            for k in range(1, n)]


def _net_cov(rho, K, factor_one_mutant=False):
    """the truncated net covariance NC(K) = 1 + 2 sum_{k<=K} rho_k
    (the reviewer object; the full sum is the r304-F1 zero-sum
    tautology); the mutant drops the factor 2 (the r304-m1 form)."""
    fac = 1 if factor_one_mutant else 2
    return 1 + fac * sum(rho[:K])


def _k0_rule(rho_abs, rho_small, k0_max, k_full):
    """the sealed r304 short-range rule: k0 = the smallest k in
    [1, k0_max] with |med rho_j| <= rho_small for ALL j in
    (k, k_full]; returns None if no such k exists (exact)."""
    for k in range(1, k0_max + 1):
        if all(rho_abs[j - 1] <= rho_small
               for j in range(k + 1, k_full + 1)):
            return k
    return None


