def _bar_r301(jk_min, need, sl_nact, sl_cv2p, cv_flat, link, ladder,
              b2_bound, sl_natom, sl_lloc, loc_grow):
    """the sealed r301 NEFF adjudication as exact decision logic:
    MARGIN_FRAGILE iff jk_min < NEED; B1_OK iff sl_nact - sl_cv2p
    >= NEED (the disclosed reparametrization; wards probe-side);
    B2_OK iff the composed bound slope >= NEED; B3_OK iff sl_natom
    >= NEED and slope(l_loc) <= +0.05; NEFF_DERIVED(B1) iff B1_OK
    and sl_cv2p <= CV_FLAT and the count link is full; else
    NEFF_SPLIT(fired) / NEFF_STILL_EMPIRICAL."""
    fragile = jk_min < need
    b1 = sl_nact - sl_cv2p >= need
    b2 = b2_bound >= need
    b3 = sl_natom >= need and sl_lloc <= loc_grow
    if b1 and sl_cv2p <= cv_flat and link == ladder:
        verdict = "NEFF_DERIVED"
    elif b1 or b2 or b3:
        verdict = "NEFF_SPLIT"
    else:
        verdict = "NEFF_STILL_EMPIRICAL"
    return verdict, (b1, b2, b3), fragile


def _bar_r302(sl_chi, chi_flat, sl_surv, surv_flat, ks13, ks23,
              ks_stat, fs_dev, fs_bar, link, ladder, ws, ws_bar,
              ks_k, gain, amp_bar):
    """the sealed r302 UNIF adjudication as exact decision logic:
    B1_OK iff sl_chi <= CHI_FLAT and sl_surv >= SURV_FLAT;
    STATIONARY iff both KS distances <= KS_STAT; TRANSIENT iff the
    held-out finite-size dev <= FS_BAR; UNIF_DERIVED(B1 + A2) iff
    B1_OK and STATIONARY and TRANSIENT and full count link and
    sl_chi <= 0; else UNIF_SPLIT / UNIF_STILL_EMPIRICAL."""
    b1 = sl_chi <= chi_flat and sl_surv >= surv_flat
    stationary = ks13 <= ks_stat and ks23 <= ks_stat
    transient = fs_dev <= fs_bar
    b2 = ws <= ws_bar and ks_k <= ks_stat
    b3 = gain <= amp_bar
    if b1 and stationary and transient and link == ladder \
            and sl_chi <= 0:
        verdict = "UNIF_DERIVED"
    elif b1 or b2 or b3:
        verdict = "UNIF_SPLIT"
    else:
        verdict = "UNIF_STILL_EMPIRICAL"
    return verdict, (b1, b2, b3), stationary, transient


def _bar_r303(prop_dev, prop_bar, half_dev, half_tol, chi_miss,
              slp_miss, chi_band, slp_band, miss_f):
    """the sealed r303 adjudication as exact decision logic:
    REGRESS_CONFIRMED iff the invariance devs <= PROP_BAR (else
    LEVELS_INDEPENDENT); HALF_CONJ_REFUTED iff the 1/2-conversion
    dev > HALF_CONJ_TOL; family F reproduces iff chi_miss <=
    CHI_BAND and both slope misses <= SLP_BAND, clearly misses iff
    one exceeds MISS_F x its band; MIXING_SUFFICIENT iff (a)
    reproduces and (b), (c) clearly miss; IRRELEVANT iff all
    reproduce; else INSUFFICIENT."""
    regress = ("REGRESS_CONFIRMED" if prop_dev <= prop_bar
               else "LEVELS_INDEPENDENT")
    half = ("HALF_CONJ_REFUTED" if half_dev > half_tol
            else "HALF_CONJ_HOLDS")
    rep = [cm <= chi_band and all(s <= slp_band for s in sm)
           for cm, sm in zip(chi_miss, slp_miss)]
    clear = [cm >= miss_f * chi_band
             or any(s >= miss_f * slp_band for s in sm)
             for cm, sm in zip(chi_miss, slp_miss)]
